INSERT INTO `service_templates` (`id`, `name`, `slug`, `service`, `description`, `icon`, `structure`, `is_system`, `created_at`) VALUES (1,'Web Development Proposal','web-development','Web Development','Complete website development proposal — 20 sections from requirements to launch.','code-slash','[{\"title\":\"Cover\",\"page_type\":\"cover\",\"blocks\":[{\"type\":\"cover\",\"data\":{\"eyebrow\":\"Website Development Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"A modern, fast and conversion-focused website built to grow your business.\"}}]},{\"title\":\"Introduction\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Introduction\",\"text\":\"Dear {{client_name}},\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Thank you for considering <b>{{company_name}}</b> for your new website. We have reviewed your requirements and prepared this proposal outlining our recommended approach, deliverables, timeline and investment.</p><p>Our goal is simple: to build a website for <b>{{client_company}}</b> that looks exceptional, loads instantly, ranks well on search engines and turns visitors into customers.</p>\"}},{\"type\":\"quote\",\"data\":{\"text\":\"Your website is your best salesperson — it works 24 hours a day, 7 days a week.\",\"author\":\"{{company_name}}\",\"style\":\"card\"}}]},{\"title\":\"About Us\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"About Us\",\"text\":\"Who We Are\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"image_text\",\"data\":{\"src\":\"\",\"side\":\"right\",\"img_width\":40,\"img_height\":260,\"title\":\"{{company_name}}\",\"html\":\"<p>{{company_name}} is a full-service digital agency helping ambitious businesses grow through beautiful design, robust technology and data-driven marketing.</p><p>Our team of designers, developers and strategists has delivered hundreds of successful projects for clients across the world — from start-ups to established enterprises.</p>\"}},{\"type\":\"spacer\",\"data\":{\"height\":8}},{\"type\":\"stats\",\"data\":{\"columns\":\"4\",\"style\":\"card\",\"items\":[{\"value\":\"250+\",\"label\":\"Projects\",\"icon\":\"trophy\"},{\"value\":\"98%\",\"label\":\"Happy Clients\",\"icon\":\"emoji-smile\"},{\"value\":\"10+\",\"label\":\"Years\",\"icon\":\"award\"},{\"value\":\"24/7\",\"label\":\"Support\",\"icon\":\"chat-dots\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Why Choose Us\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"people\",\"title\":\"Dedicated Team\",\"text\":\"A single point of contact and a senior team assigned to your project.\"},{\"icon\":\"bullseye\",\"title\":\"Results Focused\",\"text\":\"Every decision is tied to your business goals and measurable KPIs.\"},{\"icon\":\"shield-check\",\"title\":\"Reliable Delivery\",\"text\":\"Transparent timelines, weekly updates and on-time launches.\"}]}}]},{\"title\":\"Requirements & Objectives\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Understanding Your Needs\",\"text\":\"Client Requirements\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Based on our discussions, {{client_company}} requires a professional website that clearly communicates its services, builds trust and generates qualified enquiries.</p>\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"circle-check\",\"columns\":\"1\",\"items\":[{\"text\":\"A modern, professional design aligned with your brand\"},{\"text\":\"Easy content management without technical knowledge\"},{\"text\":\"Lead capture forms and clear calls-to-action\"},{\"text\":\"Fast performance on mobile and desktop\"},{\"text\":\"A solid SEO foundation from day one\"}]}},{\"type\":\"spacer\",\"data\":{\"height\":10}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Goals\",\"text\":\"Project Objectives\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"graph-up-arrow\",\"title\":\"Grow Leads\",\"text\":\"Increase qualified enquiries through optimised user journeys.\"},{\"icon\":\"award\",\"title\":\"Build Credibility\",\"text\":\"Showcase your expertise with a premium brand presence.\"},{\"icon\":\"speedometer2\",\"title\":\"Improve Speed\",\"text\":\"Achieve 90+ PageSpeed scores for better UX and rankings.\"}]}}]},{\"title\":\"Proposed Solution\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Our Approach\",\"text\":\"Proposed Solution\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We propose a custom-designed, fully responsive website built on a modern CMS. The website will be engineered for speed, security and search visibility, with an intuitive admin panel so your team can update content with ease.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Website Features\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"2\",\"items\":[{\"text\":\"Custom responsive design\"},{\"text\":\"Content management system\"},{\"text\":\"Contact & quote request forms\"},{\"text\":\"Blog / news section\"},{\"text\":\"Google Analytics & Search Console\"},{\"text\":\"WhatsApp & social integration\"},{\"text\":\"Image galleries & portfolio\"},{\"text\":\"SSL security & backups\"},{\"text\":\"Multi-language ready\"},{\"text\":\"Cookie consent & GDPR basics\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Pages Included\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"table\",\"data\":{\"title\":\"\",\"headers\":\"Page, Purpose\",\"striped\":true,\"rows\":[{\"cells\":\"Home | First impression, key services & calls-to-action\"},{\"cells\":\"About | Company story, team and values\"},{\"cells\":\"Services | Detailed service pages\"},{\"cells\":\"Portfolio | Case studies and project gallery\"},{\"cells\":\"Blog | News and SEO content\"},{\"cells\":\"Contact | Form, map and contact details\"}]}}]},{\"title\":\"Technology & Design\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Under The Hood\",\"text\":\"Technology Stack\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"bordered\",\"items\":[{\"icon\":\"code-slash\",\"title\":\"Front-end\",\"text\":\"HTML5, CSS3, Bootstrap 5 and JavaScript for a fast, accessible interface.\"},{\"icon\":\"server\",\"title\":\"Back-end\",\"text\":\"PHP & MySQL or WordPress CMS on reliable cloud hosting.\"},{\"icon\":\"cloud\",\"title\":\"Infrastructure\",\"text\":\"SSL, CDN, daily backups and uptime monitoring.\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"UI/UX Design\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We design every page around your users. Clear navigation, strong visual hierarchy and persuasive calls-to-action guide visitors toward enquiring or buying.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Responsive Design\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Over 60% of web traffic is mobile. Your website will adapt perfectly to phones, tablets, laptops and large desktop screens.</p>\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"plain\",\"items\":[{\"icon\":\"phone\",\"title\":\"Mobile\",\"text\":\"Thumb-friendly layouts\"},{\"icon\":\"tablet\",\"title\":\"Tablet\",\"text\":\"Optimised grids\"},{\"icon\":\"display\",\"title\":\"Desktop\",\"text\":\"Rich, immersive layouts\"}]}}]},{\"title\":\"SEO, Speed & Security\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Built To Perform\",\"text\":\"SEO, Speed & Security\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Search Engine Optimisation\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"1\",\"items\":[{\"text\":\"Clean semantic HTML and schema markup\"},{\"text\":\"Optimised titles, meta descriptions and headings\"},{\"text\":\"XML sitemap, robots.txt and Search Console setup\"},{\"text\":\"SEO-friendly URLs and internal linking\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Speed Optimisation\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"1\",\"items\":[{\"text\":\"Image compression & lazy loading\"},{\"text\":\"Minified CSS/JS and browser caching\"},{\"text\":\"CDN delivery and Core Web Vitals tuning\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Security\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"1\",\"items\":[{\"text\":\"SSL certificate and HTTPS everywhere\"},{\"text\":\"Firewall, malware scanning and login protection\"},{\"text\":\"Automated daily backups\"}]}}]},{\"title\":\"Development Process\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"How We Work\",\"text\":\"Development Process\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"process\",\"data\":{\"columns\":\"4\",\"items\":[{\"icon\":\"search\",\"title\":\"Discovery\",\"text\":\"Workshops, research and sitemap planning.\"},{\"icon\":\"palette\",\"title\":\"Design\",\"text\":\"Wireframes and high-fidelity UI designs.\"},{\"icon\":\"code-slash\",\"title\":\"Development\",\"text\":\"Coding, CMS integration and testing.\"},{\"icon\":\"rocket-takeoff\",\"title\":\"Launch\",\"text\":\"Go-live, training and ongoing support.\"}]}},{\"type\":\"spacer\",\"data\":{\"height\":10}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Schedule\",\"text\":\"Timeline\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"timeline\",\"data\":{\"items\":[{\"date\":\"Week 1\",\"title\":\"Discovery & Planning\",\"text\":\"Kick-off meeting, requirements and sitemap.\"},{\"date\":\"Week 2-3\",\"title\":\"UI/UX Design\",\"text\":\"Homepage and inner page designs with two revision rounds.\"},{\"date\":\"Week 4-6\",\"title\":\"Development\",\"text\":\"Responsive build, CMS setup and integrations.\"},{\"date\":\"Week 7\",\"title\":\"Testing & QA\",\"text\":\"Cross-browser testing, speed and SEO checks.\"},{\"date\":\"Week 8\",\"title\":\"Launch & Training\",\"text\":\"Deployment, handover and team training.\"}]}}]},{\"title\":\"Pricing\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Investment\",\"text\":\"Pricing\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"pricing_table\",\"data\":{\"title\":\"Project Investment\",\"rows\":[{\"service\":\"UI/UX Design\",\"description\":\"Custom design for up to 8 pages\",\"qty\":1,\"price\":900},{\"service\":\"Website Development\",\"description\":\"Responsive build + CMS\",\"qty\":1,\"price\":1600},{\"service\":\"SEO Setup\",\"description\":\"On-page SEO, sitemap, analytics\",\"qty\":1,\"price\":300},{\"service\":\"Speed & Security\",\"description\":\"Optimisation, SSL, backups\",\"qty\":1,\"price\":200}],\"tax_rate\":0,\"note\":\"All prices are in {{currency}}. This quotation is valid until {{expiry_date}}.\"}},{\"type\":\"spacer\",\"data\":{\"height\":8}},{\"type\":\"table\",\"data\":{\"title\":\"Payment Schedule\",\"headers\":\"Milestone, Percentage, Due\",\"striped\":true,\"rows\":[{\"cells\":\"Project kick-off | 50% | On acceptance\"},{\"cells\":\"Design approval | 25% | End of week 3\"},{\"cells\":\"Website launch | 25% | On go-live\"}]}}]},{\"title\":\"Terms & Conditions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"The Fine Print\",\"text\":\"Terms & Conditions\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"terms\",\"data\":{\"title\":\"\",\"size\":12,\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Hosting & domain.</b> Renewal fees for hosting and domains are the client\'s responsibility.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\"}}]},{\"title\":\"Contact\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Next Steps\",\"text\":\"Let\'s Get Started\",\"subtitle\":\"Accepting this proposal is simple — review the details, click \\\"Accept Proposal\\\" and we will schedule your kick-off call within 48 hours.\",\"level\":\"h2\"}},{\"type\":\"numbered_list\",\"data\":{\"title\":\"\",\"items\":[{\"text\":\"Accept this proposal online or sign below.\"},{\"text\":\"Receive your deposit invoice and project onboarding pack.\"},{\"text\":\"Kick-off meeting to align on goals, content and timeline.\"}]}},{\"type\":\"spacer\",\"data\":{\"height\":6}},{\"type\":\"signature\",\"data\":{\"left_name\":\"\",\"left_role\":\"Project Director\"}},{\"type\":\"spacer\",\"data\":{\"height\":6}},{\"type\":\"contact\",\"data\":{\"style\":\"card\"}}]}]',1,'2026-10-17 11:15:27');
INSERT INTO `service_templates` (`id`, `name`, `slug`, `service`, `description`, `icon`, `structure`, `is_system`, `created_at`) VALUES (2,'Web Design Proposal','web-design','Web Design','UI/UX focused proposal covering strategy, wireframes, visual design and deliverables.','palette','[{\"title\":\"Cover\",\"page_type\":\"cover\",\"blocks\":[{\"type\":\"cover\",\"data\":{\"eyebrow\":\"Web Design Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"Beautiful, user-centred design that elevates your brand online.\"}}]},{\"title\":\"Introduction & Goals\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Introduction\",\"text\":\"Hello {{client_name}},\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We are delighted to present our web design proposal for <b>{{client_company}}</b>. This document outlines how we will create a stunning, intuitive design that reflects your brand and delights your customers.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Design Goals\",\"text\":\"What We Will Achieve\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"brush\",\"title\":\"Elevate The Brand\",\"text\":\"A distinctive visual identity across every page.\"},{\"icon\":\"person-check\",\"title\":\"Delight Users\",\"text\":\"Effortless navigation and clear content hierarchy.\"},{\"icon\":\"graph-up-arrow\",\"title\":\"Convert Visitors\",\"text\":\"Strategic layouts that guide users to action.\"}]}}]},{\"title\":\"UI/UX Strategy\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Strategy\",\"text\":\"UI/UX Strategy\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Great design starts with understanding people. We research your audience, competitors and business goals to define user journeys that feel natural and lead to conversions.</p>\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"circle-check\",\"columns\":\"1\",\"items\":[{\"text\":\"User personas and journey mapping\"},{\"text\":\"Competitor and inspiration analysis\"},{\"text\":\"Information architecture & sitemap\"},{\"text\":\"Accessibility (WCAG) considerations\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Design Process\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"process\",\"data\":{\"columns\":\"4\",\"items\":[{\"icon\":\"search\",\"title\":\"Research\",\"text\":\"Audience & competitor analysis.\"},{\"icon\":\"layout-text-window\",\"title\":\"Wireframes\",\"text\":\"Low-fidelity page structure.\"},{\"icon\":\"palette\",\"title\":\"Visual Design\",\"text\":\"High-fidelity mockups.\"},{\"icon\":\"check-circle\",\"title\":\"Handoff\",\"text\":\"Specs and assets for developers.\"}]}}]},{\"title\":\"Wireframes & Visual Design\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Design Phases\",\"text\":\"Wireframes\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Wireframes define the structure of each page — content blocks, navigation and calls-to-action — before visual styling is applied. This allows fast feedback and alignment.</p>\"}},{\"type\":\"image\",\"data\":{\"src\":\"\",\"caption\":\"Example wireframe (replace with your own)\",\"width\":100,\"height\":220,\"radius\":12}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Visual Design\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We then bring the wireframes to life with your brand colours, typography, imagery and micro-interactions to create a premium, cohesive look.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Responsive Design\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Every layout is designed for mobile, tablet and desktop breakpoints so your website looks perfect everywhere.</p>\"}}]},{\"title\":\"Deliverables & Timeline\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"What You Get\",\"text\":\"Deliverables\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"2\",\"items\":[{\"text\":\"Sitemap & user flows\"},{\"text\":\"Wireframes for all key pages\"},{\"text\":\"High-fidelity designs (desktop + mobile)\"},{\"text\":\"Interactive clickable prototype\"},{\"text\":\"Style guide (colours, typography, components)\"},{\"text\":\"Exported assets & developer handoff\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Schedule\",\"text\":\"Timeline\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"timeline\",\"data\":{\"items\":[{\"date\":\"Week 1\",\"title\":\"Research & Strategy\",\"text\":\"Discovery workshop and sitemap.\"},{\"date\":\"Week 2\",\"title\":\"Wireframes\",\"text\":\"Structure for all key pages.\"},{\"date\":\"Week 3-4\",\"title\":\"Visual Design\",\"text\":\"High-fidelity designs and revisions.\"},{\"date\":\"Week 5\",\"title\":\"Prototype & Handoff\",\"text\":\"Clickable prototype and design system.\"}]}}]},{\"title\":\"Pricing\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Investment\",\"text\":\"Pricing\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"pricing_table\",\"data\":{\"title\":\"Design Investment\",\"rows\":[{\"service\":\"UX Research & Strategy\",\"description\":\"Workshop, personas, sitemap\",\"qty\":1,\"price\":400},{\"service\":\"Wireframes\",\"description\":\"Up to 8 pages\",\"qty\":1,\"price\":450},{\"service\":\"Visual Design\",\"description\":\"Desktop + mobile designs\",\"qty\":1,\"price\":1100},{\"service\":\"Prototype & Style Guide\",\"description\":\"Figma prototype + design system\",\"qty\":1,\"price\":350}],\"tax_rate\":0,\"note\":\"All prices are in {{currency}}. This quotation is valid until {{expiry_date}}.\"}}]},{\"title\":\"Terms & Conditions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"The Fine Print\",\"text\":\"Terms & Conditions\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"terms\",\"data\":{\"title\":\"\",\"size\":12,\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Revisions.</b> Two rounds of revisions are included per design phase.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\"}}]},{\"title\":\"Contact\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Next Steps\",\"text\":\"Let\'s Get Started\",\"subtitle\":\"Accepting this proposal is simple — review the details, click \\\"Accept Proposal\\\" and we will schedule your kick-off call within 48 hours.\",\"level\":\"h2\"}},{\"type\":\"numbered_list\",\"data\":{\"title\":\"\",\"items\":[{\"text\":\"Accept this proposal online or sign below.\"},{\"text\":\"Receive your deposit invoice and project onboarding pack.\"},{\"text\":\"Kick-off meeting to align on goals, content and timeline.\"}]}},{\"type\":\"spacer\",\"data\":{\"height\":6}},{\"type\":\"signature\",\"data\":{\"left_name\":\"\",\"left_role\":\"Project Director\"}},{\"type\":\"spacer\",\"data\":{\"height\":6}},{\"type\":\"contact\",\"data\":{\"style\":\"card\"}}]}]',1,'2026-10-17 11:15:27');
INSERT INTO `service_templates` (`id`, `name`, `slug`, `service`, `description`, `icon`, `structure`, `is_system`, `created_at`) VALUES (3,'SEO Proposal','seo','SEO','Monthly SEO retainer: audit, keyword research, technical, on-page, local SEO and link building.','graph-up-arrow','[{\"title\":\"Cover\",\"page_type\":\"cover\",\"blocks\":[{\"type\":\"cover\",\"data\":{\"eyebrow\":\"SEO Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"A data-driven SEO strategy to increase rankings, traffic and revenue.\"}}]},{\"title\":\"SEO Introduction\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Introduction\",\"text\":\"Grow Your Organic Visibility\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Dear {{client_name}},</p><p>Search engine optimisation is one of the highest-ROI marketing channels available. This proposal outlines how {{company_name}} will help <b>{{client_company}}</b> rank higher on Google, attract qualified visitors and convert them into customers.</p>\"}},{\"type\":\"stats\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"value\":\"93%\",\"label\":\"of online experiences begin with a search engine\",\"icon\":\"search\"},{\"value\":\"75%\",\"label\":\"of users never scroll past page one\",\"icon\":\"bar-chart\"},{\"value\":\"14.6%\",\"label\":\"average close rate of SEO leads\",\"icon\":\"graph-up\"}]}}]},{\"title\":\"Website Analysis\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Where You Are Now\",\"text\":\"Current Website Analysis\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Our initial review of your website identified the following opportunities:</p>\"}},{\"type\":\"table\",\"data\":{\"title\":\"\",\"headers\":\"Area, Current Status, Priority\",\"striped\":true,\"rows\":[{\"cells\":\"Page speed | Needs improvement | High\"},{\"cells\":\"Mobile usability | Good | Medium\"},{\"cells\":\"Meta titles & descriptions | Missing on several pages | High\"},{\"cells\":\"Backlink profile | Limited authority | High\"},{\"cells\":\"Google Business Profile | Not optimised | Medium\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Targets\",\"text\":\"SEO Objectives\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"circle-check\",\"columns\":\"1\",\"items\":[{\"text\":\"Rank on page one for priority keywords\"},{\"text\":\"Increase organic traffic by 100% in 12 months\"},{\"text\":\"Improve conversion rate from organic visitors\"},{\"text\":\"Dominate local search results in your area\"}]}}]},{\"title\":\"Strategy\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Our Strategy\",\"text\":\"Keyword Research & Technical SEO\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We identify the keywords your customers actually search for, prioritising those with strong commercial intent and achievable competition.</p>\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"search\",\"title\":\"Keyword Research\",\"text\":\"Competitor gap analysis and intent mapping.\"},{\"icon\":\"tools\",\"title\":\"Technical SEO\",\"text\":\"Crawlability, indexation, Core Web Vitals and schema.\"},{\"icon\":\"file-earmark-text\",\"title\":\"On-Page SEO\",\"text\":\"Titles, headings, content and internal links.\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Content Strategy\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We plan and produce high-quality, SEO-optimised content — service pages, blog posts and guides — that answer your customers\' questions and earn links.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Local SEO\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"2\",\"items\":[{\"text\":\"Google Business Profile optimisation\"},{\"text\":\"Local citations and NAP consistency\"},{\"text\":\"Review generation strategy\"},{\"text\":\"Location landing pages\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Link Building\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>White-hat outreach, digital PR and guest posting on relevant, authoritative websites to build your domain authority.</p>\"}}]},{\"title\":\"Reporting & Deliverables\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Transparency\",\"text\":\"Monthly Reporting\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Every month you receive a clear report covering rankings, traffic, conversions and the work completed — plus a call to discuss results and next steps.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Monthly Deliverables\",\"text\":\"Expected Deliverables\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"2\",\"items\":[{\"text\":\"Keyword ranking report\"},{\"text\":\"4 SEO blog articles\"},{\"text\":\"10 quality backlinks\"},{\"text\":\"Technical health monitoring\"},{\"text\":\"On-page optimisation of 5 pages\"},{\"text\":\"Monthly strategy call\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Roadmap\",\"text\":\"Timeline\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"timeline\",\"data\":{\"items\":[{\"date\":\"Month 1\",\"title\":\"Audit & Foundations\",\"text\":\"Full audit, keyword research and technical fixes.\"},{\"date\":\"Month 2-3\",\"title\":\"Optimisation\",\"text\":\"On-page SEO, content and local SEO.\"},{\"date\":\"Month 4-6\",\"title\":\"Authority Building\",\"text\":\"Link building and content expansion.\"},{\"date\":\"Month 6+\",\"title\":\"Scale & Grow\",\"text\":\"Expand keywords and conversion optimisation.\"}]}}]},{\"title\":\"Monthly Pricing\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Investment\",\"text\":\"Monthly Pricing\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"comparison_table\",\"data\":{\"title\":\"SEO Packages\",\"headers\":\"Starter | Growth | Premium\",\"prices\":\"$350/mo | $650/mo | $1,200/mo\",\"highlight\":2,\"rows\":[{\"feature\":\"Target keywords\",\"values\":\"10 | 25 | 50\"},{\"feature\":\"Blog articles / month\",\"values\":\"2 | 4 | 8\"},{\"feature\":\"Backlinks / month\",\"values\":\"5 | 10 | 20\"},{\"feature\":\"Local SEO\",\"values\":\"yes | yes | yes\"},{\"feature\":\"Technical SEO\",\"values\":\"Basic | Advanced | Advanced\"},{\"feature\":\"Strategy call\",\"values\":\"no | yes | yes\"}]}},{\"type\":\"spacer\",\"data\":{\"height\":10}},{\"type\":\"pricing_table\",\"data\":{\"title\":\"Selected Package\",\"rows\":[{\"service\":\"SEO Growth Package\",\"description\":\"Monthly SEO retainer\",\"qty\":1,\"price\":650},{\"service\":\"One-time SEO Audit & Setup\",\"description\":\"Technical fixes and tracking\",\"qty\":1,\"price\":300}],\"tax_rate\":0,\"note\":\"Monthly fees are billed in advance. Minimum engagement of 6 months.\"}}]},{\"title\":\"Terms & Conditions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"The Fine Print\",\"text\":\"Terms & Conditions\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"terms\",\"data\":{\"title\":\"\",\"size\":12,\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Results.</b> SEO results depend on many external factors; no specific ranking can be guaranteed.</li><li><b>Minimum term.</b> SEO services require a minimum 6-month commitment.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\"}}]},{\"title\":\"Contact\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Next Steps\",\"text\":\"Let\'s Get Started\",\"subtitle\":\"Accepting this proposal is simple — review the details, click \\\"Accept Proposal\\\" and we will schedule your kick-off call within 48 hours.\",\"level\":\"h2\"}},{\"type\":\"numbered_list\",\"data\":{\"title\":\"\",\"items\":[{\"text\":\"Accept this proposal online or sign below.\"},{\"text\":\"Receive your deposit invoice and project onboarding pack.\"},{\"text\":\"Kick-off meeting to align on goals, content and timeline.\"}]}},{\"type\":\"spacer\",\"data\":{\"height\":6}},{\"type\":\"signature\",\"data\":{\"left_name\":\"\",\"left_role\":\"Project Director\"}},{\"type\":\"spacer\",\"data\":{\"height\":6}},{\"type\":\"contact\",\"data\":{\"style\":\"card\"}}]}]',1,'2026-10-17 11:15:27');
INSERT INTO `service_templates` (`id`, `name`, `slug`, `service`, `description`, `icon`, `structure`, `is_system`, `created_at`) VALUES (4,'Graphics Design Proposal','graphic-design','Graphic Design','Branding & graphic design proposal with creative direction, concepts and revision policy.','brush','[{\"title\":\"Cover\",\"page_type\":\"cover\",\"blocks\":[{\"type\":\"cover\",\"data\":{\"eyebrow\":\"Graphic Design Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"Creative design that captures attention and communicates your brand.\"}}]},{\"title\":\"Introduction\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Introduction\",\"text\":\"Hello {{client_name}},\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Thank you for inviting {{company_name}} to submit a proposal for your graphic design project. We specialise in creating visuals that are not only beautiful, but strategically designed to help <b>{{client_company}}</b> stand out.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Your Brief\",\"text\":\"Design Requirements\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"circle-check\",\"columns\":\"1\",\"items\":[{\"text\":\"Logo and visual identity refresh\"},{\"text\":\"Business stationery (cards, letterhead)\"},{\"text\":\"Social media templates\"},{\"text\":\"Marketing collateral (brochure, flyers)\"}]}}]},{\"title\":\"Brand & Creative Direction\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Strategy\",\"text\":\"Brand Understanding\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Before designing, we immerse ourselves in your brand — your audience, values, personality and competitors — so every design decision is purposeful.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Creative Direction\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"palette\",\"title\":\"Colour Palette\",\"text\":\"A distinctive palette that evokes the right emotions.\"},{\"icon\":\"type\",\"title\":\"Typography\",\"text\":\"Typefaces that are legible and on-brand.\"},{\"icon\":\"images\",\"title\":\"Imagery Style\",\"text\":\"Consistent photography and illustration direction.\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Design Concepts\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We will present <b>3 unique initial concepts</b>. You choose your favourite direction and we refine it into the final design.</p>\"}}]},{\"title\":\"Deliverables & Revisions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"What You Get\",\"text\":\"Deliverables\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"service_cards\",\"data\":{\"columns\":\"2\",\"show_price\":true,\"items\":[{\"icon\":\"brush\",\"title\":\"Logo & Identity\",\"description\":\"Primary logo, variations and brand guidelines.\",\"features\":\"Primary & secondary logo\\nIcon / favicon\\nColour & type guide\\nAll file formats\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"},{\"icon\":\"file-earmark-text\",\"title\":\"Print & Digital\",\"description\":\"Stationery and marketing materials.\",\"features\":\"Business cards\\nLetterhead\\nBrochure design\\n10 social templates\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Revisions\",\"text\":\"Revision Policy\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Each deliverable includes <b>three rounds of revisions</b>. Additional revisions are charged at an hourly rate. Revisions must be requested within 14 days of delivery.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Schedule\",\"text\":\"Timeline\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"timeline\",\"data\":{\"items\":[{\"date\":\"Week 1\",\"title\":\"Discovery & Moodboards\",\"text\":\"Brand questionnaire and creative direction.\"},{\"date\":\"Week 2\",\"title\":\"Initial Concepts\",\"text\":\"Presentation of 3 concepts.\"},{\"date\":\"Week 3\",\"title\":\"Refinement\",\"text\":\"Revisions on selected concept.\"},{\"date\":\"Week 4\",\"title\":\"Final Delivery\",\"text\":\"Final files and brand guidelines.\"}]}}]},{\"title\":\"Pricing\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Investment\",\"text\":\"Pricing\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"pricing_table\",\"data\":{\"title\":\"Design Investment\",\"rows\":[{\"service\":\"Logo Design\",\"description\":\"3 concepts, 3 revisions\",\"qty\":1,\"price\":450},{\"service\":\"Brand Guidelines\",\"description\":\"Colour, typography, usage rules\",\"qty\":1,\"price\":250},{\"service\":\"Stationery Set\",\"description\":\"Business card & letterhead\",\"qty\":1,\"price\":150},{\"service\":\"Social Media Templates\",\"description\":\"10 editable templates\",\"qty\":1,\"price\":200}],\"tax_rate\":0,\"note\":\"All prices are in {{currency}}. This quotation is valid until {{expiry_date}}.\"}}]},{\"title\":\"Terms & Conditions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"The Fine Print\",\"text\":\"Terms & Conditions\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"terms\",\"data\":{\"title\":\"\",\"size\":12,\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Source files.</b> Editable source files are delivered after final payment.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\"}}]}]',1,'2026-10-17 11:15:27');
INSERT INTO `service_templates` (`id`, `name`, `slug`, `service`, `description`, `icon`, `structure`, `is_system`, `created_at`) VALUES (5,'Video Editing Proposal','video-editing','Video Editing','Video editing proposal: storytelling, motion graphics, colour grading and sound design.','film','[{\"title\":\"Cover\",\"page_type\":\"cover\",\"blocks\":[{\"type\":\"cover\",\"data\":{\"eyebrow\":\"Video Editing Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"Professional editing that turns raw footage into compelling stories.\"}}]},{\"title\":\"Project Overview\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Overview\",\"text\":\"Project Overview\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Dear {{client_name}}, we are excited to help <b>{{client_company}}</b> produce engaging video content. This proposal covers our editing approach, deliverables, timeline and investment.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Your Brief\",\"text\":\"Video Requirements\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"table\",\"data\":{\"title\":\"\",\"headers\":\"Requirement, Details\",\"striped\":true,\"rows\":[{\"cells\":\"Video type | Promotional / brand video\"},{\"cells\":\"Length | 60–90 seconds + short cut-downs\"},{\"cells\":\"Formats | 16:9, 9:16 and 1:1\"},{\"cells\":\"Footage | Supplied by client\"},{\"cells\":\"Music | Licensed royalty-free track\"}]}}]},{\"title\":\"Editing Approach\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Our Craft\",\"text\":\"Editing Style & Storytelling\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We craft a clear narrative arc — hook, story and call-to-action — paced to keep viewers watching until the end.</p>\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"film\",\"title\":\"Storytelling\",\"text\":\"Structure and pacing that keeps viewers engaged.\"},{\"icon\":\"magic\",\"title\":\"Motion Graphics\",\"text\":\"Animated titles, lower thirds and logo reveals.\"},{\"icon\":\"palette\",\"title\":\"Colour Grading\",\"text\":\"Cinematic, consistent colour across all shots.\"}]}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"broadcast\",\"title\":\"Sound Design\",\"text\":\"Music, SFX, voice clean-up and mixing.\"},{\"icon\":\"phone-vibrate\",\"title\":\"Social Ready\",\"text\":\"Vertical cut-downs for Reels, Shorts and TikTok.\"},{\"icon\":\"translate\",\"title\":\"Subtitles\",\"text\":\"Accurate captions for silent autoplay.\"}]}}]},{\"title\":\"Deliverables & Timeline\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"What You Get\",\"text\":\"Deliverables\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"1\",\"items\":[{\"text\":\"1 × master video (60–90 sec, 4K)\"},{\"text\":\"3 × social cut-downs (15–30 sec)\"},{\"text\":\"Burned-in & SRT subtitles\"},{\"text\":\"Thumbnail design\"},{\"text\":\"Project files on request\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Revisions\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Two rounds of revisions are included. Feedback should be consolidated and provided with timestamps.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Schedule\",\"text\":\"Timeline\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"timeline\",\"data\":{\"items\":[{\"date\":\"Day 1-2\",\"title\":\"Footage Review\",\"text\":\"Selects and story outline.\"},{\"date\":\"Day 3-5\",\"title\":\"First Cut\",\"text\":\"Rough edit with music.\"},{\"date\":\"Day 6-8\",\"title\":\"Fine Cut\",\"text\":\"Motion graphics, grade and sound.\"},{\"date\":\"Day 9-10\",\"title\":\"Final Delivery\",\"text\":\"Exports in all formats.\"}]}}]},{\"title\":\"Pricing\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Investment\",\"text\":\"Pricing\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"pricing_table\",\"data\":{\"title\":\"Video Editing Investment\",\"rows\":[{\"service\":\"Master Video Edit\",\"description\":\"Up to 90 seconds\",\"qty\":1,\"price\":600},{\"service\":\"Motion Graphics Package\",\"description\":\"Titles, lower thirds, logo animation\",\"qty\":1,\"price\":250},{\"service\":\"Colour Grading & Sound\",\"description\":\"Grade, mix and mastering\",\"qty\":1,\"price\":200},{\"service\":\"Social Cut-downs\",\"description\":\"Vertical & square versions\",\"qty\":3,\"price\":80}],\"tax_rate\":0,\"note\":\"All prices are in {{currency}}. This quotation is valid until {{expiry_date}}.\"}}]},{\"title\":\"Terms & Conditions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"The Fine Print\",\"text\":\"Terms & Conditions\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"terms\",\"data\":{\"title\":\"\",\"size\":12,\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Footage & licences.</b> The client warrants that it owns or has licensed all supplied footage and assets.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\"}}]}]',1,'2026-10-17 11:15:27');
INSERT INTO `service_templates` (`id`, `name`, `slug`, `service`, `description`, `icon`, `structure`, `is_system`, `created_at`) VALUES (6,'Mobile App Development Proposal','mobile-app','Mobile App Development','Android & iOS app proposal with backend/API, admin panel, testing and deployment.','phone','[{\"title\":\"Cover\",\"page_type\":\"cover\",\"blocks\":[{\"type\":\"cover\",\"data\":{\"eyebrow\":\"Mobile App Development Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"A powerful, scalable mobile app for Android and iOS.\"}}]},{\"title\":\"Project Overview\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Overview\",\"text\":\"Project Overview\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Dear {{client_name}},</p><p>{{company_name}} is pleased to propose the design and development of a cross-platform mobile application for <b>{{client_company}}</b>. The app will deliver a fast, intuitive experience on both Android and iOS, backed by a secure cloud backend and an admin panel.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Goals\",\"text\":\"App Objectives\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"circle-check\",\"columns\":\"1\",\"items\":[{\"text\":\"Deliver a seamless experience on Android and iOS\"},{\"text\":\"Increase customer engagement and retention\"},{\"text\":\"Enable secure user accounts and data\"},{\"text\":\"Provide real-time notifications\"},{\"text\":\"Give your team full control via an admin panel\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Audience\",\"text\":\"Target Audience\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>The primary audience is smartphone users aged 18–45 who value speed, simplicity and convenience. The design will prioritise one-handed use and accessibility.</p>\"}}]},{\"title\":\"Scope of Work\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Scope\",\"text\":\"Features & Technology\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"service_cards\",\"data\":{\"columns\":\"2\",\"show_price\":true,\"items\":[{\"icon\":\"palette\",\"title\":\"UI/UX Design\",\"description\":\"Modern, intuitive app screens.\",\"features\":\"User flows\\nWireframes\\nHigh-fidelity UI\\nClickable prototype\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"},{\"icon\":\"android2\",\"title\":\"Android Development\",\"description\":\"Native-quality Android app.\",\"features\":\"Flutter / React Native\\nMaterial design\\nOffline support\\nPlay Store ready\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"},{\"icon\":\"apple\",\"title\":\"iOS Development\",\"description\":\"Polished iPhone experience.\",\"features\":\"Human Interface guidelines\\nFace ID support\\nApp Store ready\\niPad compatible\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"},{\"icon\":\"server\",\"title\":\"Backend / API\",\"description\":\"Secure, scalable cloud backend.\",\"features\":\"REST API\\nDatabase design\\nCloud hosting\\nPayment gateway\",\"price\":\"\",\"bg\":\"\",\"color\":\"\"}]}}]},{\"title\":\"Platform Features\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Platform\",\"text\":\"Core Platform Features\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"key\",\"title\":\"Authentication\",\"text\":\"Email, phone OTP and social login with secure tokens.\"},{\"icon\":\"bell\",\"title\":\"Notifications\",\"text\":\"Push notifications with segmentation and scheduling.\"},{\"icon\":\"kanban\",\"title\":\"Admin Panel\",\"text\":\"Web dashboard to manage users, content and analytics.\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Testing & Quality Assurance\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"2\",\"items\":[{\"text\":\"Unit and integration testing\"},{\"text\":\"Manual QA on real devices\"},{\"text\":\"Performance and security testing\"},{\"text\":\"Beta testing via TestFlight & Play Console\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"App Store Deployment\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We handle app store listings, screenshots, compliance checks and submission to the Google Play Store and Apple App Store.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Maintenance\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>After launch we provide 60 days of free bug-fix support, followed by optional monthly maintenance covering OS updates, monitoring and improvements.</p>\"}}]},{\"title\":\"Timeline\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Schedule\",\"text\":\"Timeline\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"timeline\",\"data\":{\"items\":[{\"date\":\"Week 1-2\",\"title\":\"Discovery & UX\",\"text\":\"Requirements, user flows and wireframes.\"},{\"date\":\"Week 3-4\",\"title\":\"UI Design\",\"text\":\"High-fidelity screens and prototype.\"},{\"date\":\"Week 5-10\",\"title\":\"Development\",\"text\":\"App, backend and admin panel sprints.\"},{\"date\":\"Week 11\",\"title\":\"Testing\",\"text\":\"QA, beta testing and fixes.\"},{\"date\":\"Week 12\",\"title\":\"Launch\",\"text\":\"Store submission and go-live.\"}]}}]},{\"title\":\"Pricing\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Investment\",\"text\":\"Pricing\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"pricing_table\",\"data\":{\"title\":\"App Development Investment\",\"rows\":[{\"service\":\"UI/UX Design\",\"description\":\"Up to 25 screens\",\"qty\":1,\"price\":2500},{\"service\":\"Android & iOS App\",\"description\":\"Cross-platform development\",\"qty\":1,\"price\":9000},{\"service\":\"Backend & API\",\"description\":\"Database, API, hosting setup\",\"qty\":1,\"price\":4000},{\"service\":\"Admin Panel\",\"description\":\"Web dashboard\",\"qty\":1,\"price\":2500},{\"service\":\"Testing & Deployment\",\"description\":\"QA and store submission\",\"qty\":1,\"price\":1200}],\"tax_rate\":0,\"note\":\"All prices are in {{currency}}. This quotation is valid until {{expiry_date}}.\"}},{\"type\":\"spacer\",\"data\":{\"height\":8}},{\"type\":\"table\",\"data\":{\"title\":\"Payment Schedule\",\"headers\":\"Milestone, Percentage, Due\",\"striped\":true,\"rows\":[{\"cells\":\"Kick-off | 30% | On acceptance\"},{\"cells\":\"Design approval | 20% | Week 4\"},{\"cells\":\"Beta release | 30% | Week 11\"},{\"cells\":\"Store launch | 20% | Week 12\"}]}}]},{\"title\":\"Terms & Conditions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"The Fine Print\",\"text\":\"Terms & Conditions\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"terms\",\"data\":{\"title\":\"\",\"size\":12,\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Developer accounts.</b> Apple Developer and Google Play accounts are registered in the client\'s name and paid by the client.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\"}}]}]',1,'2026-10-17 11:15:27');
INSERT INTO `service_templates` (`id`, `name`, `slug`, `service`, `description`, `icon`, `structure`, `is_system`, `created_at`) VALUES (7,'Social Media Marketing Proposal','social-media','Social Media Marketing','Monthly social media management: strategy, content, reels, community & paid ads.','megaphone','[{\"title\":\"Cover\",\"page_type\":\"cover\",\"blocks\":[{\"type\":\"cover\",\"data\":{\"eyebrow\":\"Social Media Marketing Proposal\",\"title\":\"{{proposal_title}}\",\"subtitle\":\"Strategic social media that builds community and drives growth.\"}}]},{\"title\":\"Introduction & Audit\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Introduction\",\"text\":\"Hi {{client_name}},\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Social media is where your customers spend their time. This proposal outlines how {{company_name}} will grow <b>{{client_company}}</b>\'s presence, engagement and sales through consistent, high-quality content and targeted advertising.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Where You Are\",\"text\":\"Social Media Audit\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"table\",\"data\":{\"title\":\"\",\"headers\":\"Platform, Followers, Engagement, Opportunity\",\"striped\":true,\"rows\":[{\"cells\":\"Instagram | 1,200 | Low | Reels & consistency\"},{\"cells\":\"Facebook | 2,500 | Low | Community & ads\"},{\"cells\":\"LinkedIn | 300 | Medium | Thought leadership\"},{\"cells\":\"TikTok | — | — | New channel\"}]}}]},{\"title\":\"Strategy\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Strategy\",\"text\":\"Our Social Media Strategy\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"bullseye\",\"title\":\"Awareness\",\"text\":\"Reach new audiences with shareable content.\"},{\"icon\":\"chat-dots\",\"title\":\"Engagement\",\"text\":\"Build a loyal community through conversation.\"},{\"icon\":\"cart-check\",\"title\":\"Conversion\",\"text\":\"Turn followers into leads and customers.\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Content Strategy\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Our content mix balances education, inspiration, entertainment and promotion, built around content pillars tailored to your brand.</p>\"}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Content Calendar\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"table\",\"data\":{\"title\":\"\",\"headers\":\"Day, Content, Platform\",\"striped\":true,\"rows\":[{\"cells\":\"Monday | Educational carousel | Instagram, LinkedIn\"},{\"cells\":\"Wednesday | Reel / short video | Instagram, TikTok\"},{\"cells\":\"Friday | Customer story / testimonial | Facebook, Instagram\"},{\"cells\":\"Weekly | Stories & polls | Instagram, Facebook\"}]}}]},{\"title\":\"Content Production\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Production\",\"text\":\"Graphic Design & Video\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>All posts are custom designed in your brand style. We produce eye-catching graphics, carousels and short-form videos optimised for each platform.</p>\"}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"image\",\"title\":\"Graphic Design\",\"text\":\"Branded posts, carousels and story designs.\"},{\"icon\":\"camera-video\",\"title\":\"Video / Reels\",\"text\":\"Edited reels, captions and trending audio.\"},{\"icon\":\"calendar-check\",\"title\":\"Posting Schedule\",\"text\":\"Posts published at peak engagement times.\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Community Management\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"1\",\"items\":[{\"text\":\"Respond to comments and DMs within business hours\"},{\"text\":\"Engage with followers and relevant accounts\"},{\"text\":\"Monitor brand mentions and reviews\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Paid Advertising\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We plan, launch and optimise Meta (Facebook & Instagram) ad campaigns with precise targeting, A/B testing and retargeting. Ad spend is paid directly by the client.</p>\"}}]},{\"title\":\"Analytics & Deliverables\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Measurement\",\"text\":\"Analytics & Monthly Reporting\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>We track reach, engagement, follower growth, website clicks and conversions. A monthly report and strategy call keep you informed and allow continuous improvement.</p>\"}},{\"type\":\"stats\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"value\":\"+150%\",\"label\":\"Target reach growth\",\"icon\":\"graph-up-arrow\"},{\"value\":\"+80%\",\"label\":\"Target engagement\",\"icon\":\"heart\"},{\"value\":\"3x\",\"label\":\"Target ad ROAS\",\"icon\":\"cash-coin\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Every Month\",\"text\":\"Deliverables\",\"subtitle\":\"\",\"level\":\"h3\"}},{\"type\":\"list\",\"data\":{\"title\":\"\",\"marker\":\"check\",\"columns\":\"2\",\"items\":[{\"text\":\"16 feed posts (graphics & carousels)\"},{\"text\":\"8 Reels / short videos\"},{\"text\":\"20 stories\"},{\"text\":\"Community management\"},{\"text\":\"Ad campaign management\"},{\"text\":\"Monthly analytics report\"}]}}]},{\"title\":\"Monthly Pricing\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Investment\",\"text\":\"Monthly Pricing\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"pricing_table\",\"data\":{\"title\":\"Monthly Retainer\",\"rows\":[{\"service\":\"Social Media Management\",\"description\":\"3 platforms, 16 posts\",\"qty\":1,\"price\":600},{\"service\":\"Reels Production\",\"description\":\"8 edited short videos\",\"qty\":1,\"price\":400},{\"service\":\"Paid Ads Management\",\"description\":\"Meta ads setup & optimisation\",\"qty\":1,\"price\":250}],\"tax_rate\":0,\"note\":\"Fees billed monthly in advance. Ad spend is not included.\"}}]},{\"title\":\"Terms & Conditions\",\"page_type\":\"content\",\"blocks\":[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"The Fine Print\",\"text\":\"Terms & Conditions\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"terms\",\"data\":{\"title\":\"\",\"size\":12,\"html\":\"<ol><li><b>Acceptance.</b> This proposal becomes a binding agreement once accepted in writing or electronically by {{client_company}}.</li><li><b>Payment.</b> Invoices are payable within 7 days. Work begins once the initial deposit has been received.</li><li><b>Revisions.</b> The number of revision rounds is limited to what is specified in this proposal. Additional changes are billed at our standard hourly rate.</li><li><b>Client responsibilities.</b> The client agrees to provide content, feedback and approvals in a timely manner. Delays may affect the timeline.</li><li><b>Intellectual property.</b> Upon full payment, ownership of the final deliverables transfers to the client. {{company_name}} may showcase the work in its portfolio.</li><li><b>Third-party costs.</b> Domains, hosting, premium plugins, stock assets and advertising spend are not included unless stated.</li><li><b>Confidentiality.</b> Both parties agree to keep confidential information private.</li><li><b>Cancellation.</b> Either party may terminate with 14 days written notice. Work completed up to that date is payable.</li><li><b>Approvals.</b> Content calendars are shared one week in advance for approval.</li><li><b>Ad spend.</b> Advertising budgets are paid directly to the platforms by the client.</li><li><b>Validity.</b> This proposal is valid until {{expiry_date}}.</li></ol>\"}}]}]',1,'2026-10-17 11:15:27');
INSERT INTO `content_library` (`id`, `name`, `category`, `description`, `blocks`, `created_at`, `updated_at`) VALUES (1,'About Company','Company','','[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"About Us\",\"text\":\"Who We Are\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"image_text\",\"data\":{\"src\":\"\",\"side\":\"right\",\"img_width\":40,\"img_height\":260,\"title\":\"{{company_name}}\",\"html\":\"<p>{{company_name}} is a full-service digital agency helping ambitious businesses grow through beautiful design, robust technology and data-driven marketing.</p><p>Our team of designers, developers and strategists has delivered hundreds of successful projects for clients across the world — from start-ups to established enterprises.</p>\"}},{\"type\":\"spacer\",\"data\":{\"height\":8}},{\"type\":\"stats\",\"data\":{\"columns\":\"4\",\"style\":\"card\",\"items\":[{\"value\":\"250+\",\"label\":\"Projects\",\"icon\":\"trophy\"},{\"value\":\"98%\",\"label\":\"Happy Clients\",\"icon\":\"emoji-smile\"},{\"value\":\"10+\",\"label\":\"Years\",\"icon\":\"award\"},{\"value\":\"24/7\",\"label\":\"Support\",\"icon\":\"chat-dots\"}]}},{\"type\":\"heading\",\"data\":{\"eyebrow\":\"\",\"text\":\"Why Choose Us\",\"subtitle\":\"\",\"level\":\"h3\",\"style\":\"plain\",\"_s\":{\"mb\":8,\"mt\":6}}},{\"type\":\"feature_cards\",\"data\":{\"columns\":\"3\",\"style\":\"card\",\"items\":[{\"icon\":\"people\",\"title\":\"Dedicated Team\",\"text\":\"A single point of contact and a senior team assigned to your project.\"},{\"icon\":\"bullseye\",\"title\":\"Results Focused\",\"text\":\"Every decision is tied to your business goals and measurable KPIs.\"},{\"icon\":\"shield-check\",\"title\":\"Reliable Delivery\",\"text\":\"Transparent timelines, weekly updates and on-time launches.\"}]}}]','2026-10-17 11:15:27',NULL);
INSERT INTO `content_library` (`id`, `name`, `category`, `description`, `blocks`, `created_at`, `updated_at`) VALUES (2,'Web Development Introduction','Introductions','','[{\"type\":\"heading\",\"data\":{\"eyebrow\":\"Introduction\",\"text\":\"Dear {{client_name}},\",\"subtitle\":\"\",\"level\":\"h2\"}},{\"type\":\"text\",\"data\":{\"html\":\"<p>Thank you for considering <b>{{company_name}}</b> for your new website. We have prepared this proposal to outline our approach, deliverables, timeline and investment for <b>{{client_company}}</b>.</p>\"}}]','2026-10-17 11:15:27',NULL);
